{"command": "# The CortexA53 entries are linker-generated thunks (erratum workarounds), not real functions.
# These are branch islands. Let's trace what they jump to by looking at the actual function symbols
# Let me look at proper function symbols (uppercase T = global text)
nm -n /tmp/libmonosgen_debug 2>/dev/null | grep " [tTW] " | awk '
{
  cur = strtonum("0x" substr($1, 1))
  if (cur <= 0x2f4b20 && $3 !~ /^__CortexA53/) fn1 = $3 " @ " $1
  if (cur <= 0x2f4c84 && $3 !~ /^__CortexA53/) fn2 = $3 " @ " $1
}
END { print "0x2f4b20 is in: " fn1; print "0x2f4c84 is in: " fn2 }
'", "description": "Find real functions excluding thunks"}

{"command": "# $x are ARM mapping symbols. Let me filter those out too and look for real function names
nm -n /tmp/libmonosgen_debug 2>/dev/null | grep " [tTW] " | grep -v '^\S* [tTW] \$[xdt]' | grep -v '__CortexA53' | awk '
{
  cur = strtonum("0x" substr($1, 1))
  if (cur <= 0x2f4b20) fn1 = $3 " @ 0x" $1
  if (cur <= 0x2f4c84) fn2 = $3 " @ 0x" $1
  if (cur <= 0x2c1a40) fn3 = $3 " @ 0x" $1
  if (cur <= 0x16de04) fn4 = $3 " @ 0x" $1
}
END { print "0x2f4b20: " fn1; print "0x2f4c84: " fn2; print "0x2c1a40: " fn3; print "0x16de04: " fn4 }
'", "description": "Find real function symbols"}

{"command": "# Those are linker-generated atomic stubs. The addresses 0x2f4b20 and 0x2f4c84 fall in thunk territory.
# Let me check if these are actually in a different section. Let's use objdump to disassemble around those addresses
# Actually let me check DWARF info directly with addr2line using the actual stripped binary + debug
# Or let me check readelf for function ranges via .debug_info
# Let me try a different approach - use readelf to dump functions and find which ones span these addresses

pip install pyelftools 2>/dev/null | tail -1
python3 -c "
import struct
from elftools.elf.elffile import ELFFile
from elftools.dwarf.descriptions import describe_form_class

with open('/tmp/libmonosgen_debug', 'rb') as f:
    elf = ELFFile(f)
    symtab = elf.get_section_by_name('.symtab')

    targets = [0x2f4b20, 0x2f4c84]

    # Get all FUNC symbols sorted by address
    funcs = []
    for sym in symtab.iter_symbols():
        if sym['st_info']['type'] == 'STT_FUNC' and sym['st_value'] > 0:
            funcs.append((sym['st_value'], sym['st_size'], sym.name))

    funcs.sort()

    for target in targets:
        for addr, size, name in funcs:
            if addr <= target < addr + size:
                print(f'0x{target:x}: {name} (0x{addr:x} + 0x{target-addr:x}, size=0x{size:x})')
                break
        else:
            # Find nearest before
            prev = None
            for addr, size, name in funcs:
                if addr <= target:
                    prev = (addr, size, name)
                else:
                    break
            if prev:
                print(f'0x{target:x}: nearest is {prev[2]} @ 0x{prev[0]:x} (size=0x{prev[1]:x}, offset=+0x{target-prev[0]:x})')
" 2>&1", "description": "Use pyelftools for precise lookup", "initial_wait": 30}

