python3 -c "
from elftools.elf.elffile import ELFFile

with open('/tmp/libmonosgen_debug', 'rb') as f:
    elf = ELFFile(f)

    targets = [0x2f4b20, 0x2f4c84]

    # Find which section contains these addresses
    for target in targets:
        for section in elf.iter_sections():
            start = section['sh_addr']
            end = start + section['sh_size']
            if start <= target < end:
                print(f'0x{target:x}: section {section.name} (0x{start:x}-0x{end:x})')
                break

    # Check DWARF compilation unit subprograms
    dwarf = elf.get_dwarf_info()
    for target in targets:
        found = False
        for cu in dwarf.iter_CUs():
            for die in cu.iter_DIEs():
                if die.tag == 'DW_TAG_subprogram':
                    if 'DW_AT_low_pc' in die.attributes and 'DW_AT_high_pc' in die.attributes:
                        low = die.attributes['DW_AT_low_pc'].value
                        high_attr = die.attributes['DW_AT_high_pc']
                        if high_attr.form.startswith('DW_FORM_addr'):
                            high = high_attr.value
                        else:
                            high = low + high_attr.value
                        if low <= target < high:
                            name = die.attributes.get('DW_AT_name')
                            if name:
                                print(f'0x{target:x}: DWARF function {name.value.decode()} (0x{low:x}-0x{high:x})')
                            found = True
                            break
            if found:
                break
" 2>&1

