{"command": "# The 0x2f4b20 and 0x2f4c84 are in a RW data segment, not executable code.
# Let's see what named data objects are around those addresses
python3 -c "
from elftools.elf.elffile import ELFFile

with open('/tmp/libmonosgen_debug', 'rb') as f:
    elf = ELFFile(f)
    symtab = elf.get_section_by_name('.symtab')

    # Get all OBJECT symbols in the range
    objs = []
    for sym in symtab.iter_symbols():
        if sym['st_value'] >= 0x2f3810 and sym['st_value'] < 0x2f6a18:
            if sym.name and not sym.name.startswith('\$'):
                objs.append((sym['st_value'], sym['st_size'], sym.name, sym['st_info']['type']))

    objs.sort()
    for addr, size, name, stype in objs:
        if addr <= 0x2f4c84 and (size == 0 or addr + size > 0x2f4b20):
            print(f'  0x{addr:08x} size=0x{size:x} {stype} {name}')
" 2>&1", "description": "Check data symbols at those addresses"}
